import { HierarchyRectangularNode } from '@visx/hierarchy/lib/types';

import { InternalTreeMapLeafNode } from '../types/internal.js';

export const NODE_LEAF_PADDING = 0.5;
export const NODE_OTHER_PADDING = 1;

export const nodePadding = (
  node: HierarchyRectangularNode<InternalTreeMapLeafNode>,
): number => (node.height === 0 ? NODE_LEAF_PADDING : NODE_OTHER_PADDING);
